// Noto Sans Khmer, subsetted to just the glyphs this fixture needs (Khmer
// script, basic Latin, common punctuation) and compressed as WOFF instead
// of shipping the full 360KB variable font. Two static instances (400 and
// 700 weight) rather than one variable-weight file: a static WOFF loads
// faster and is universally supported, where the earlier variable-font
// attempt (format('truetype-variations')) may not have finished parsing in
// time for expo-print's one-shot `viewPrintFormatter` capture, which does
// not wait for @font-face loading the way normal page rendering does.
//
// Kept in their own file on purpose, same reasoning as before: a large
// base64 blob living inline in a file you actually edit is fragile — it's
// exactly the kind of thing an editor can choke on or silently discard.
//
// Why embed a font at all: iOS has no Noto Sans Khmer installed (unlike
// Android, which ships it), so without this iOS silently substitutes a
// thinner, taller-metric system font — see docs/ios-implementation-spec.md
// for why that substitution alone costs printed resolution.
export const notoSansKhmerRegularBase64 =
  '';
export const notoSansKhmerBoldBase64 =
  '';
